H.background();
const a = P.a;        // point where we take the tangent
const N = Math.max(1, Math.round(P.N)); // number of area rectangles
const mode = P.mode;  // <0.5 = tangent (secant->tangent), else area
const v = H.plot2d({ xMin: -1, xMax: 5, yMin: -1, yMax: 9 });
v.grid(); v.axes();
function f(x){ return 0.5 * x * x; }      // f(x) = x^2/2
function fp(x){ return x; }                // f'(x) = x
v.fn(f, { color: H.colors.accent, width: 3 });
if (mode < 0.5){
  // TANGENT: a secant from (a, f(a)) to (a+h, f(a+h)); h shrinks to 0 with t.
  const h = 1.8 * (0.5 + 0.5 * Math.cos(t * 1.1)) + 0.02;
  const x1 = a, x2 = a + h;
  const slope = (f(x2) - f(x1)) / h;
  v.line(x1 - 3, f(x1) - 3 * slope, x2 + 3, f(x2) + 3 * slope, { color: H.colors.accent2, width: 2 });
  v.dot(x1, f(x1), { r: 6, fill: H.colors.warn });
  v.dot(x2, f(x2), { r: 6, fill: H.colors.good });
  H.text("Tangent line:  slope = lim (h->0) [f(a+h)-f(a)]/h = f'(a)", 24, 30, { color: H.colors.ink, size: 15, weight: 700 });
  H.text("a = " + a.toFixed(1) + "   h = " + h.toFixed(3) + "   secant slope = " + slope.toFixed(3) + "   ->  f'(a) = " + fp(a).toFixed(2), 24, 52, { color: H.colors.sub, size: 13 });
  H.legend([{ label: "f(x) = x^2/2", color: H.colors.accent }, { label: "secant -> tangent", color: H.colors.accent2 }], H.W - 200, 28);
} else {
  // AREA: N Riemann rectangles from 0 to a; a sweep highlights one at a time.
  const x0 = 0, x1 = Math.max(0.5, a);
  const dx = (x1 - x0) / N;
  const active = Math.floor(t * 1.2) % N;
  let area = 0;
  for (let i = 0; i < N; i++){
    const xl = x0 + i * dx;
    const xm = xl + dx * 0.5;
    const hh = f(xm);
    area += hh * dx;
    v.rect(xl, 0, dx, hh, { fill: i === active ? H.colors.accent2 : "rgba(124,196,255,0.25)", stroke: H.colors.accent, width: 1 });
  }
  const exact = (x1 * x1 * x1) / 6; // integral of x^2/2 from 0 to x1
  H.text("Area under the curve:  sum of rectangles -> integral", 24, 30, { color: H.colors.ink, size: 15, weight: 700 });
  H.text("from 0 to " + x1.toFixed(1) + "   N = " + N + "   Riemann sum = " + area.toFixed(3) + "   exact = " + exact.toFixed(3), 24, 52, { color: H.colors.sub, size: 13 });
  H.legend([{ label: "f(x) = x^2/2", color: H.colors.accent }, { label: "rectangles", color: H.colors.accent2 }], H.W - 180, 28);
}
